                stack = [(r_start, c_start)]
                while stack:
                    sr, sc = stack.pop()
                    if grid[sr][sc] != c:
                        continue
                    cells.append((sr, sc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
