                # Compute bounding box
                rs = [r for r, c in cells]
                cs = [c for r, c in cells]
                rmin, rmax = min(rs), max(rs)
                cmin, cmax = min(cs), max(cs)

                # Check if this is a hollow rectangle (border of c, interior not c)
                interior = []
                for r in range(rmin + 1, rmax):
