                    # Check original fill color from output
                    fill_colors = Counter(str(out[r][c]) for r, c in interior_bg)
                    if fill_colors:
                        fill = int(list(fill_colors.keys())[0])
                        # Record this fill color for matching
                        pass

                # If interior contains different-content, fill it appropriately
                relevant_interior = [(r, c) for r in range(rmin + 1, rmax) for c in range(cmin + 1, cmax) if grid[r][c] == bg]
                if relevant_interior:
                    # Check filled output color
                    fill_colors = {}
                    for r, c in relevant_interior:
                        fc = out[r][c]
