def find_color_box(grid, r, c, bg=6):
    row_left = c
    for cc in range(c, -1, -1):
        if grid[r][cc] != bg:
            row_left = cc
            break

    row_right = c
    for cc in range(c, w):
        if grid[r][cc] != bg:
            row_right = cc
            break

    col_top = r
    for rr in range(r, -1, -1):
        if grid[rr][c] != bg:
            col_top = rr
            break

    col_bottom = r
    for rr in range(r, h):
        if grid[rr][c] != bg:
            col_bottom = rr
            break

    return col_top, col_bottom, row_left, row_right

def tried_fill(grid, bg=6):
    h_int, w_int = len(grid), len(grid[0])
    out = [[grid[r][c] for c in range(w_int)] for r in range(h_int)]

    for r in range(h_int):
        for c in range(w_int):
            color = grid[r][c]
            if color != bg:
                continue

            try:
                top, bottom, left, right = find_color_box(grid, r, c)
            except:
                continue

            int_h = bottom - top - 1
            int_w = right - left - 1

            if int_h >= 1 and int_w >= 1:
                fill = 2 if (int_h % 2 == 0 and int_w % 2 == 0) else 7
                out[r][c] = fill

    return out

